{
  "identity": {
    "name": "Crofts Electric",
    "location": "Boise, Idaho",
    "claims": [
      {
        "statement": "Crofts Electric is a family-owned electrical services business operating in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Crofts Electric is a licensed, family-owned electrician near you in Boise, Idaho with over 16 years of service homeowners, businesses, and construction contractors."
      },
      {
        "statement": "Crofts Electric is a subsidiary entity of RC Electric LLC.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "Crofts Electric, a subsidiary of RC Electric LLC, currently specializes in five star service and top quality electrical work"
      },
      {
        "statement": "The company also operates an office location in Lexington, Kentucky.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "[redacted]’s initial Crofts Electric vision led him to start Crofts Electric in Lexington Kentucky, while he also had a strong desire to eventually also establish"
      }
    ]
  },
  "industry": {
    "industry": "Electrical Contracting",
    "activities": [
      "Residential electrical repairs and troubleshooting",
      "Electrical panel and service upgrades",
      "EV charger station installations",
      "Whole home standby generator installations",
      "Kitchen remodeling electrical wiring and fixtures",
      "Commercial space fit-outs and maintenance",
      "New construction electrical installations",
      "Smart home device wiring and automation"
    ],
    "claims": [
      {
        "statement": "The company provides residential, commercial, and construction electrical services across the Boise metropolitan area.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Serving Homeowners, Businesses & Contractors in Boise, Eagle, Nampa, Meridian, Star & Garden City, ID"
      },
      {
        "statement": "The business focuses on licensed journeyman and master electrician services rather than general handyman work.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Every electrician on our team is a certified journeyman or master electrician."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.croftselectricboise.com/",
    "claims": [
      {
        "statement": "The company maintains its primary web presence on croftselectricboise.com.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Crofts Electric Boise Idaho Electricians Repairs & Service"
      },
      {
        "statement": "The website was designed and configured by Lotus Live Design Creative Studio on the Squarespace platform.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "WEBSITE DESIGN, BRANDING & SEO BY Lotus Live Design Creative Studio A founding member of the Squarestylist Community"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Crofts Electric holds both Master Electrician and Electrical Contractor licenses in the state of Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Crofts Electric holds an Idaho Master Electrician License #CE061542 and Idaho Electrical Contractor License #ME059080 ."
      },
      {
        "statement": "The business also holds Master Electrician and Electrical Contractor licenses in the Commonwealth of Kentucky.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "KY MASTER ELECTRICIAN LICENSE #CE65316 KY KY ELECTRICAL CONTRACTOR LICENSE #ME65337 ID MASTER ELECTRICIAN LICENSE #CE061542 ID ELECTRICAL CONTRACTOR LICENSE #ME059080"
      }
    ],
    "limitations": "Licensing numbers were verified from the public footer and FAQ text on the company website; external state regulatory registries were not directly queried."
  },
  "existingSoftware": [
    {
      "product": "Squarespace",
      "purpose": "Website hosting, content management, and online lead capture forms",
      "evidence": {
        "statement": "The website assets and runtime libraries are loaded from Squarespace infrastructure.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "WEBSITE DESIGN, BRANDING & SEO BY Lotus Live Design Creative Studio A founding member of the Squarestylist Community"
      }
    },
    {
      "product": "Google Ads / Google Tag Manager",
      "purpose": "Paid search lead generation and conversion tracking",
      "evidence": {
        "statement": "The site loads Google Tag Manager with an active Google Ads conversion tag identifier AW-805112476 on its service and contact pages.",
        "label": "inference",
        "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
        "quote": null
      }
    },
    {
      "product": "Elfsight",
      "purpose": "Third-party customer review integration widget",
      "evidence": {
        "statement": "The site loads external platform script libraries from apps.elfsight.com.",
        "label": "inference",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Crofts Electric operates on standard business hours from 8:00 AM to 4:30 PM, Monday through Friday, leaving off-hours without live phone coverage.",
      "label": "fact",
      "sourceUrl": "https://www.croftselectricboise.com/",
      "quote": "Available Monday–Friday, 8am–4:30pm · Call [redacted]"
    },
    {
      "statement": "The company relies on manual, written project estimates rather than an instant quoting or self-scheduling workflow.",
      "label": "fact",
      "sourceUrl": "https://www.croftselectricboise.com/",
      "quote": "We provide free and honest written estimates for all electrical projects so you know exactly what your project will cost before work begins."
    },
    {
      "statement": "The company actively runs paid advertising campaigns to acquire electrical service calls.",
      "label": "inference",
      "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Inbound leads generated through Google Ads outside standard weekday hours (evenings and weekends) may experience delayed response times.",
      "label": "hypothesis",
      "basis": "The business lists active operating hours strictly between 8:00 AM and 4:30 PM Monday through Friday and provides only a phone number and basic web form, without visible 24/7 automated instant response or live scheduling."
    },
    {
      "problem": "Estimate requests submitted via web forms require manual review, logging, and follow-up, creating the possibility of leads slipping through during peak trade seasons.",
      "label": "hypothesis",
      "basis": "The website shows no connection to a dedicated field-service CRM or automated booking engine; all inquiries prompt manual written estimates."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Field Service Management platform (e.g., Jobber, Housecall Pro, or ServiceTitan) with built-in instant online booking and automatic SMS/email lead replies.",
      "addresses": "Captures customer details immediately, books estimate slots, and prevents manual data entry.",
      "alreadyOwned": false
    },
    {
      "solution": "After-hours answering service or automated VoIP missed-call auto-texting system.",
      "addresses": "Provides immediate engagement when prospects call during evening or weekend hours.",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "In one week, see how many calls, leads and quotes slip through, and what they are worth to you. The $500 fee is credited in full to any fix you order within 30 days.",
      "problem": "Uncertainty regarding whether Google Ads spend is losing prospects who call or submit forms outside 8:00 AM–4:30 PM hours.",
      "whyNotExistingSoftware": "Provides an immediate diagnostic assessment of real lead loss without committing to or configuring new enterprise software suites."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Every lead from every source lands in your field-service software within two minutes, gets an instant reply, and nobody forgets to call back.",
      "problem": "Web form submissions and ad leads do not receive automated immediate confirmations or fast routing to staff.",
      "whyNotExistingSoftware": "Standard Squarespace web forms do not offer native two-way SMS auto-replies or automated dispatch integration without custom integration layers."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "Squarespace web form submission hooks and Google Ads conversion events can be cleanly integrated with automated notification webhooks and dispatch tools without altering existing core web design."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "AI agents can parse customer inquiry details, send immediate scheduling confirmations, and draft preliminary triage summaries, but all technical electrical assessments and code-compliant written estimates require a licensed journeyman or master electrician."
  },
  "humanReview": [
    "Verification and approval of all technical electrical quotes and formal written estimates by a licensed journeyman or master electrician.",
    "Approval of scheduled field service appointments prior to technician dispatch."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Automated messages must not over-promise technician availability or issue preliminary pricing without on-site technical inspection."
    },
    {
      "type": "compliance",
      "description": "All electrical work recommendations must adhere strictly to Idaho state electrical codes and master contractor licensing regulations (#CE061542 / #ME059080)."
    },
    {
      "type": "security",
      "description": "Homeowner and commercial client contact information, access notes, and service addresses submitted via web forms must be transmitted and stored securely."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "Crofts Electric publishes promotional percentage discounts (e.g., 15% labor discount for new clients, 10% for repeat clients) but does not list fixed dollar prices or hourly labor rates on its public website, preventing a mathematically supportable value calculation under ForgeX rules."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "Master Electrician and Licensed Contractor"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Master Electrician and Licensed Contractor",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "[redacted], Master Electrician and Licensed Contracto r, opened Crofts Electric after achieving 14 years of advanced training and work experience."
      }
    ],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.croftselectricboise.com/"
      },
      {
        "kind": "web form",
        "value": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
        "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate"
      }
    ]
  },
  "discovery": {
    "questions": [
      "When prospective residential or commercial clients submit estimate requests on your website outside your 8:00 AM–4:30 PM window, what is your current follow-up process?",
      "How are you currently tracking which Google Ads inquiries result in completed, paid electrical projects versus missed opportunities?",
      "What software tools does your team currently use to log incoming inquiries and dispatch electricians across Boise and surrounding areas?"
    ],
    "outreachSubject": "Handling after-hours electrical inquiries from Crofts Electric's Google Ads",
    "outreachBody": "Hi [redacted],\n\nI noticed Crofts Electric is running search advertising for electrical service calls in Boise while operating weekday hours from 8:00 AM to 4:30 PM.\n\nWhen homeowners or commercial property managers request an estimate in the evening or over the weekend, does your system send an instant automated reply to keep them engaged, or do those requests wait until the team opens the following morning?\n\nAt ForgeX, we help trade contractors ensure every inbound ad and web lead gets an immediate acknowledgment and gets tracked into your dispatch queue within two minutes, without adding admin burden to your technicians.\n\nIf you'd be open to a brief conversation about how other electrical contractors handle after-hours lead capture, please let me know.\n\nBest regards,\n\n[Founder Name]\nFounder, ForgeX\n[Founder Phone]\n[Founder Email]\n[ForgeX Postal Address]\n\nIf you prefer not to receive future emails regarding this, reply with 'unsubscribe' and we will remove your contact details immediately."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.croftselectricboise.com/",
        "usedFor": "Business identity, operating hours, service area, license numbers, promotional discounts, and general company claims."
      },
      {
        "url": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "usedFor": "Founder background ([redacted]), parent company entity (RC Electric LLC), licensing details, and company history."
      },
      {
        "url": "https://www.croftselectricboise.com/our-expert-boise-electricians-skills-qualifications",
        "usedFor": "Technician training structure, journeyman and master electrician qualifications, and licensing details."
      },
      {
        "url": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
        "usedFor": "Contact channel verification, estimate request instructions, and detection of Google Ads tracking scripts."
      },
      {
        "url": "https://www.croftselectricboise.com/boise-idaho-electrical-electrician-services-discounts",
        "usedFor": "Promotional structure and commercial pricing policy evaluation."
      },
      {
        "url": "https://www.croftselectricboise.com/cart",
        "usedFor": "Assessment of potential ecommerce functionality."
      },
      {
        "url": "https://www.croftselectricboise.com/electrical-service-circuit-panel-upgrades-installation",
        "usedFor": "Service-specific offering evaluation for panel and service upgrades."
      },
      {
        "url": "https://www.croftselectricboise.com/licensed-commercial-electrical-contractors-boise-idaho",
        "usedFor": "Commercial contracting capability and building automation offerings."
      }
    ],
    "limitations": [
      "The exact number of field technicians or office staff employed in the Boise location is not stated on the website, making it impossible to verify whether the business meets ForgeX's 10 to 75 staff threshold.",
      "No specific dollar pricing is published on the site, precluding supportable commercial ROI calculations.",
      "No direct business email address is published on the site; only a telephone number and a web contact form are provided."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "Crofts Electric is an owner-led electrical contractor operating in Boise, Idaho, and shows evidence of paid lead generation via active Google Ads tracking. However, its exact staff size cannot be verified from the website alone (the business presents as a family-owned operation expanding from Kentucky to Boise, but whether it employs 10 to 75 staff is unconfirmed). In addition, operational challenges regarding lead loss or response lag are plausible hypotheses rather than publicly verifiable broken workflows. Pursuing later allows confirmation of staff size and intake volume before initiating an active sales motion."
  }
}
